public static class Final1113ContactDebug{public static string Run(){var c=UnityEngine.Object.FindObjectsByType<CommanderAnt>(FindObjectsInactive.Exclude).First(c=>c.CurrentResourceNode);var n=c.CurrentResourceNode;var outwards=Vector3.ProjectOnPlane(c.Position-n.transform.position,Vector3.up).normalized;string result="";foreach(var p in new[]{c.Position,n.transform.position+outwards,n.transform.position}){if(Physics.Raycast(p+Vector3.up*8,Vector3.down,out var h,24,1<<8)){MeshyWorkContact.TryRadius(n,c.GetComponent<AntVisual>().MotionName,outwards,h.point.y,out float r);result+=$"p{p:F3} ground{h.point:F3} hit={h.collider.name} radius={r:F4}\n";}}return result+"stop="+c.Agent.stoppingDistance+" base="+c.Agent.baseOffset;}}
